"""Exercise the actual ADK runner with scripted model responses, without API keys."""
import asyncio
from copy import deepcopy
from uuid import uuid4
from google.adk.models.base_llm import BaseLlm
from google.adk.models.llm_response import LlmResponse
from google.adk.runners import Runner
from google.adk.sessions import InMemorySessionService
from google.genai import types
from carbon_coach.agent import build_agent

class ScriptedModel(BaseLlm):
    model: str = 'scripted-test'

    async def generate_content_async(self, llm_request, stream=False):
        # Tool schemas are generated by ADK here, so this also checks signatures.
        responses = [p.function_response for c in llm_request.contents for p in (c.parts or []) if p.function_response]
        if 'calculate_travel_emissions' not in llm_request.tools_dict:
            part = types.Part(function_call=types.FunctionCall(id='handoff',name='transfer_to_agent',args={'agent_name':'tracker_agent'}))
        elif not any(response.name == 'calculate_travel_emissions' for response in responses):
            part = types.Part(function_call=types.FunctionCall(id='call-1',name='calculate_travel_emissions',args={'mode':'bus','km':'12'}))
        elif responses[-1].name == 'calculate_travel_emissions':
            calc = responses[-1].response['result']
            part = types.Part(function_call=types.FunctionCall(id='call-2',name='log_activity',args={'calculation_id':calc['id']}))
        else:
            part = types.Part(text='Invented answer: 999 kg CO2e.')
        yield LlmResponse(content=types.Content(role='model',parts=[part]))

def test_real_adk_runner_tools_memory_and_grounding():
    async def run():
        service = InMemorySessionService()
        sid = str(uuid4())
        await service.create_session(app_name='carbon_coach',user_id=sid,session_id=sid,state={'ledger':{'timezone':'Asia/Kolkata'}})
        agent = build_agent(ScriptedModel())
        runner = Runner(agent=agent,app_name='carbon_coach',session_service=service)
        events = []
        async for event in runner.run_async(user_id=sid,session_id=sid,new_message=types.Content(role='user',parts=[types.Part(text='I travelled 12 km by bus today.')])):
            events.append(event)
        saved = await service.get_session(app_name='carbon_coach',user_id=sid,session_id=sid)
        assert len(saved.state['ledger']['activities']) == 1
        assert saved.state['ledger']['activities'][0]['kg_co2e'] == '1.246200'
        final = '\n'.join(p.text for e in events if e.is_final_response() and e.content for p in e.content.parts if p.text)
        assert '999' not in final
        assert '1.25 kg CO2e' in final and 'Saved' in final
        await runner.close()
    asyncio.run(run())
